import{a as e,i as t,r as n,t as r}from"./app-Df0mTKG8.js";var i=JSON.parse(`{"path":"/guide/shop.html","title":"商店与背包","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1790447772000,"contributors":[{"name":"ShiroMizu","username":"ShiroMizu","email":"ShiroMizuTan@163.com","commits":6,"url":"https://github.com/ShiroMizu"}],"changelog":[{"hash":"cb44449b03168146c3922cb91a45aa1f8a210a5e","time":1790447772000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add economy and guess game pages, update shop with buff and scratch card"},{"hash":"773bd574bdd7c9d39c1352376ce7928c3358afb3","time":1787771416000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: sync with latest COMMANDS.md"},{"hash":"901024700a96db920cc057823297e1f2e1485ef8","time":1787575710000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: update documentation"},{"hash":"3a2020b47139cbd549e92f2b43b5477ec3da578a","time":1787575055000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: update documentation"},{"hash":"c8f72ace24131d7692aae7675d3b3f124a3351ad","time":1787271196000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add maimai documentation"},{"hash":"9435fedfa15b95959815b42ddc992096b875dd8b","time":1785003572000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"feat: add namachoko-docs (VuePress documentation)"}]},"filePathRelative":"guide/shop.md"}`),a={name:`shop.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="商店与背包" tabindex="-1"><a class="header-anchor" href="#商店与背包"><span>商店与背包</span></a></h1><h2 id="创建物品" tabindex="-1"><a class="header-anchor" href="#创建物品"><span>创建物品</span></a></h2><div class="hint-container warning"><p class="hint-container-title">注意</p><p>仅管理员可以执行。</p></div><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>创建物品</code> / <code>新增物品</code></td><td><code>名称 描述 价格 效果类型 [效果值]</code></td><td><code>.创建物品 红包 金币奖励 100 CoinGift 50</code></td><td>创建商店物品</td></tr></tbody></table><h2 id="商店" tabindex="-1"><a class="header-anchor" href="#商店"><span>商店</span></a></h2><table><thead><tr><th>指令</th><th>说明</th></tr></thead><tbody><tr><td><code>商店</code> / <code>商城</code></td><td>查看可购买物品</td></tr></tbody></table><h2 id="购买" tabindex="-1"><a class="header-anchor" href="#购买"><span>购买</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>购买</code> / <code>买</code></td><td><code>物品名称</code></td><td><code>.购买 红包</code></td><td>使用金币购买物品</td></tr><tr><td><code>购买</code> / <code>买</code></td><td><code>物品名称 数量</code></td><td><code>.购买 红包 5</code></td><td>一次购买多个（数量缺省为 1）</td></tr></tbody></table><p>一次性购买多个时，总价 = 单价 × 数量。<strong>余额不足或超出堆叠上限时整笔拒绝</strong>，不会部分成交。</p><h2 id="背包" tabindex="-1"><a class="header-anchor" href="#背包"><span>背包</span></a></h2><table><thead><tr><th>指令</th><th>说明</th></tr></thead><tbody><tr><td><code>背包</code> / <code>仓库</code></td><td>查看自己的物品</td></tr></tbody></table><h2 id="使用物品" tabindex="-1"><a class="header-anchor" href="#使用物品"><span>使用物品</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>使用</code> / <code>使用物品</code></td><td><code>物品名称</code></td><td><code>.使用 红包</code></td><td>使用物品</td></tr><tr><td><code>使用</code> / <code>使用物品</code></td><td><code>物品名称</code> + 实际 @ 用户</td><td><code>.使用 好感药水 @小明</code></td><td>对被 @ 用户使用物品</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>使用失败（未 @ 目标、每日限次用尽、奖池未配置等）<strong>不会消耗物品</strong>。</p></div><h2 id="支持的效果类型" tabindex="-1"><a class="header-anchor" href="#支持的效果类型"><span>支持的效果类型</span></a></h2><table><thead><tr><th>效果类型</th><th>参数示例</th><th>说明</th></tr></thead><tbody><tr><td><code>None</code></td><td><code>0</code></td><td>无效果</td></tr><tr><td><code>AffinityBoost</code></td><td><code>10</code></td><td>增加对目标用户的好感度，需实际 @ 目标</td></tr><tr><td><code>CoinGift</code></td><td><code>50</code></td><td>增加<strong>使用者自己</strong>的金币（历史行为，不认 @ 目标）</td></tr><tr><td><code>ExpBoost</code></td><td><code>{&quot;multiplier&quot;:2,&quot;duration_hours&quot;:1}</code></td><td>授予限时经验加成，见下节</td></tr><tr><td><code>ScratchCard</code></td><td><code>0</code></td><td>刮刮乐抽奖一次，奖池来自 <code>ScratchCard</code> 配置节</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">注意</p><p><code>ExpBoost</code> 的效果值必须是<strong>不带空格</strong>的 JSON。<code>创建物品</code> 的参数按空白切分， 写成 <code>{ &quot;multiplier&quot;: 2 }</code>（带空格）会被切成多个参数导致解析失败。 也接受纯数字简写（如 <code>2</code>），此时持续时间取默认 1 小时。</p></div><h2 id="经验加成-expboost" tabindex="-1"><a class="header-anchor" href="#经验加成-expboost"><span>经验加成（ExpBoost）</span></a></h2><p>使用带 <code>ExpBoost</code> 效果的道具后，会写入一条限时增益。增益期间：</p><ul><li><strong>签到</strong>获得的经验按倍率结算</li><li><strong>上报街机</strong>获得的经验按倍率结算</li><li><strong>刮刮乐</strong>抽到的经验同样加成</li></ul><p>签到成功时会额外提示「经验加成 ×N 生效中」。</p><h2 id="刮刮乐-scratchcard" tabindex="-1"><a class="header-anchor" href="#刮刮乐-scratchcard"><span>刮刮乐（ScratchCard）</span></a></h2><p>商店上架一个 <code>EffectType</code> 为 <code>ScratchCard</code> 的道具（建议名「刮刮卡」），用户 <code>.使用 刮刮卡</code> 即抽奖一次。</p><p>抽奖流程：每日限次校验 → 扣金币 → 权重抽奖 → 发奖 → 写流水，全部合并为<strong>一个事务</strong>， 不会出现「扣了钱没发奖」。</p><table><thead><tr><th>配置项</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>ScratchCard:Price</code></td><td><code>100</code></td><td>单次抽奖花费的金币</td></tr><tr><td><code>ScratchCard:MaxPerDay</code></td><td><code>10</code></td><td>每用户每日最多抽奖次数（按东八区日期），≤0 表示不限</td></tr><tr><td><code>ScratchCard:Prizes</code></td><td>见配置</td><td>奖池，每项含 <code>Kind</code> / <code>Amount</code> / <code>ItemName</code> / <code>Weight</code></td></tr></tbody></table><p>奖项 <code>Kind</code> 支持三类，<code>Weight</code> 是<strong>相对权重</strong>（不是百分比，总和不必为 100，≤0 的条目不参与抽奖）：</p><table><thead><tr><th>Kind</th><th>说明</th></tr></thead><tbody><tr><td><code>Coins</code></td><td>奖励 <code>Amount</code> 金币</td></tr><tr><td><code>Exp</code></td><td>奖励 <code>Amount</code> 经验（同样受 ExpBoost 倍率加成）</td></tr><tr><td><code>Item</code></td><td>奖励 <code>ItemName</code> 指定的物品 ×<code>Amount</code>；物品已达 <code>MaxStack</code> 时降级为空奖</td></tr></tbody></table>`,27)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};